-- ============================================================================
-- EC4: Decision Analysis & Value of Information joins the catalog, the FOURTH
-- Economics course.
--
-- Catalog row (module 'economics'; path_order 56; prereq_slug NULL, the
-- carried-over answer "no hard prerequisite inside a module") plus the three
-- capstones and their eighteen graded fields, generated by
-- /root/ec-wip-decision/gen_course.py from fields.json and the capstone
-- constants in ec4_fields.mjs. Deep seeds are three separate migrations; the
-- go-live is a fifth and is HELD until a NextGen production upload carries
-- the route /dashboard/apps/decision.
--
-- THE ONE SENTENCE THE COURSE IS. A decision tree turns uncertain money into
-- one choice by taking expectations and maxima, and information is worth
-- exactly what it can change in that choice, and nothing at all when the
-- numbers describing it cannot all be true.
--
-- THE ENGINES. engines/economics/decisionTree.js (the Decision Tree Builder
-- and Decision Studio's decision section) and engines/economics/voi.js (the
-- VOI Analyzer), as repaired before this course in EC4-0 (engines #177: the
-- Analyzer refuses percent inputs that are not distributions and withholds
-- the value of information when typed indicator numbers contradict the
-- stated outcome chances; finding D1 resolved).
--
-- THE CAPSTONE GRADES WHAT THE COURSE TEACHES A READER TO GET RIGHT: a node
-- value before its branch cost, a later choice rolled back first, a moved
-- probability, Bayes posteriors against likelihoods, gross against net, the
-- Analyzer's two actions, a Monte Carlo payoff at its mean, the brief's
-- advantage row and the half percent consistency window. Every graded field
-- clears the teaching digest by at least 40 tolerances and is moved beyond its
-- tolerance by the named mistakes (scratch/discriminate.mjs).
-- ============================================================================

insert into public.academy_apps (slug, name, module, path_order, status, prereq_slug)
values ('decision', 'Decision Analysis & Value of Information', 'economics', 56, 'coming_soon', null)
on conflict (slug) do nothing;

insert into public.academy_capstones
    (app_slug, tier, cert_tier, dataset, title, prompt, fields)
